<template>
  <div class="traffic-app">
    <main v-if="!actor" class="login-card">
      <div class="eyebrow">CAMPUS TRAFFIC · 线索协作</div><h1>交通线索平台</h1><p class="muted">让每一条线索都有可追踪的处理结果。</p>
      <el-form @submit.native.prevent="signIn"><el-form-item label="账号"><el-input v-model="login.username" autocomplete="username" label="账号" /></el-form-item><el-form-item label="密码"><el-input v-model="login.password" type="password" autocomplete="current-password" label="密码" /></el-form-item><el-button type="primary" native-type="submit" :loading="busy">登录工作台</el-button></el-form>
      <p v-if="error" role="alert" class="error">{{ error }}</p><p class="muted small">账号由平台管理员分配，登录后按角色和区域展示任务。</p>
    </main>
    <template v-else>
      <aside class="sidebar"><div class="brand">交通线索<span>协作 · 审核 · 激励</span></div><button v-for="item in navigation" :key="item.key" :disabled="busy" :class="{ active: section === item.key }" @click="changeSection(item.key)">{{ item.label }}</button><button v-if="can('identity:user:manage')" :disabled="busy" :class="{active:section==='identity'}" @click="changeSection('identity')">账户管理</button><div class="sidebar-bottom">{{ actor.username }}<br><span>{{ actor.regionCodes.join(' / ') || '暂无区域' }}</span><el-button type="text" :disabled="busy" @click="signOut">退出登录</el-button></div></aside>
      <main class="workspace" v-loading="busy">
        <header><div class="eyebrow">工作台 / {{ section === 'identity' ? '账户管理' : sectionTitle }}</div><h1>{{ section === 'identity' ? '账户管理' : sectionTitle }}</h1><p class="muted">{{ descriptions[section] }}</p></header>
        <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="notice" />
        <div class="toolbar"><el-button @click="refresh">刷新记录</el-button><span class="muted small">显示第 {{ page }} 页 · 每页 20 条</span></div>
        <section v-if="section === 'campaigns'">
          <div v-if="can('campaign:manage')" class="panel"><h2>发布专项征集</h2><el-form inline><el-form-item label="名称"><el-input v-model="campaign.title" /></el-form-item><el-form-item label="区域"><el-input v-model="campaign.regionCode" /></el-form-item><el-form-item label="单条奖励（元）"><el-input-number v-model="campaign.rewardAmount" :min="0.01" :precision="2" /></el-form-item><el-form-item label="总预算（元）"><el-input-number v-model="campaign.budgetAmount" :min="campaign.rewardAmount" :precision="2" /></el-form-item><el-form-item label="起止时间"><el-date-picker v-model="windowRange" type="datetimerange" start-placeholder="开始" end-placeholder="结束" /></el-form-item><el-button type="primary" @click="createCampaign">保存草稿</el-button></el-form></div>
          <div class="panel"><el-table :data="rows"><el-table-column prop="title" label="征集任务" min-width="180" /><el-table-column prop="regionCode" label="区域" /><el-table-column label="奖励 / 预算"><template slot-scope="s">¥{{ s.row.rewardAmount }} / ¥{{ s.row.budgetAmount }}</template></el-table-column><el-table-column label="状态"><template slot-scope="s"><el-tag>{{ label(s.row.state) }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="180"><template slot-scope="s"><el-button v-if="s.row.state === 'PUBLISHED' && can('report:submit')" type="text" @click="prepareReport(s.row)">提交线索</el-button><el-button v-if="can('campaign:manage') && s.row.state === 'DRAFT'" type="text" @click="campaignAction(s.row, 'publish')">发布</el-button><el-button v-if="can('campaign:manage') && s.row.state !== 'CLOSED'" type="text" @click="campaignAction(s.row, 'close')">关闭</el-button><el-button v-if="can('reward:manage')" type="text" @click="budget(s.row)">预算</el-button></template></el-table-column></el-table></div>
        </section>
        <section v-if="section === 'reports'">
          <div v-if="can('report:submit')" class="panel"><h2>提交交通线索</h2><el-form label-position="top"><div class="form-grid"><el-form-item label="征集任务"><el-select v-model="report.campaignId" placeholder="选择进行中的征集"><el-option v-for="item in campaigns" :key="item.id" :label="item.title" :value="item.id" /></el-select></el-form-item><el-form-item label="拍摄时间"><el-date-picker v-model="captureTime" type="datetime" /></el-form-item><el-form-item label="地点"><el-input v-model="report.location" maxlength="255" /></el-form-item><el-form-item label="证据图片（PNG/JPEG，最多5MiB）"><input type="file" accept="image/png,image/jpeg" aria-label="证据图片" @change="selectImage"></el-form-item></div><el-form-item label="情况描述"><el-input v-model="report.description" type="textarea" :rows="3" maxlength="2000" /></el-form-item><el-button type="primary" :disabled="!file || busy" @click="submitReport">提交并开始检测</el-button><span class="muted small">同一任务请勿重复提交相同图片。</span></el-form></div>
          <div class="panel"><el-table :data="rows"><el-table-column prop="id" label="编号" width="80" /><el-table-column prop="location" label="地点" /><el-table-column label="检测"><template slot-scope="s">{{ label(s.row.detectionStatus) }}</template></el-table-column><el-table-column label="审核"><template slot-scope="s">{{ label(s.row.reviewStatus) }}</template></el-table-column><el-table-column label="奖励"><template slot-scope="s">{{ label(s.row.rewardStatus) }}</template></el-table-column><el-table-column label="操作" min-width="170"><template slot-scope="s"><el-button v-if="s.row.userId === actor.userId" type="text" @click="preview('/evidence/' + s.row.evidenceId + '/content')">查看证据</el-button><span v-else class="muted small">请在审核工作台查看证据</span><el-button v-if="s.row.userId === actor.userId && s.row.reviewStatus === 'REJECTED'" type="text" @click="appeal(s.row)">申请复核</el-button></template></el-table-column></el-table></div>
        </section>
        <section v-if="section === 'reviews'">
          <div class="panel"><div class="toolbar"><el-select v-model="reviewStatus" @change="reload"><el-option label="可领取" value="READY" /><el-option label="已领取" value="CLAIMED" /><el-option label="全部记录" value="" /><el-option label="需人工转派" value="MANUAL_REQUIRED" /></el-select></div><el-table :data="rows"><el-table-column prop="reportId" label="线索" /><el-table-column prop="regionCode" label="区域" /><el-table-column label="审核阶段"><template slot-scope="s">{{ s.row.stage === 'RECHECK' ? '独立复核' : '初审' }}</template></el-table-column><el-table-column label="模型风险"><template slot-scope="s">{{ s.row.score == null ? '暂无' : s.row.score.toFixed(3) }}</template></el-table-column><el-table-column label="状态"><template slot-scope="s">{{ label(s.row.status) }}</template></el-table-column><el-table-column label="操作" min-width="220"><template slot-scope="s"><el-button v-if="s.row.status === 'READY' && can('review:claim')" type="text" @click="claim(s.row)">领取处理</el-button><el-button v-if="claims[s.row.id]" type="text" @click="openReview(s.row)">继续审核</el-button><el-button type="text" @click="audit(s.row)">操作记录</el-button><el-button v-if="can('review:manage') && !['APPROVED','REJECTED'].includes(s.row.status)" type="text" @click="reassign(s.row)">指定转派</el-button></template></el-table-column></el-table><p class="muted small">禁止审核本人提交的线索；复核必须由不同审核员完成。刷新页面后无法恢复领取凭证时，请等待租约回收或申请管理员转派。</p></div>
        </section>
        <section v-if="section === 'wallet'">
          <div class="stats"><div class="panel"><span>可用奖励</span><strong>¥{{ wallet.available || 0 }}</strong></div><div class="panel"><span>冻结金额</span><strong>¥{{ wallet.frozen || 0 }}</strong></div><div class="panel"><span>提现方式</span><strong class="stat-label">模拟结算</strong></div></div>
          <div class="panel" v-if="can('wallet:withdraw')"><h2>模拟提现申请</h2><el-input-number v-model="withdrawAmount" :precision="2" :min="0.01" /><el-select v-model="withdrawRegion"><el-option v-for="region in actor.regionCodes" :key="region" :label="region" :value="region" /></el-select><el-button type="primary" @click="withdraw">提交申请</el-button><p class="muted small">本项目未连接银行或第三方支付，不填写真实收款账户。</p></div>
          <div class="panel"><h2>奖励订单</h2><el-table :data="rows"><el-table-column prop="reportId" label="线索" /><el-table-column prop="amount" label="金额（元）" /><el-table-column label="状态"><template slot-scope="s">{{ label(s.row.state) }}</template></el-table-column></el-table></div>
          <div class="panel"><h2>钱包流水</h2><el-table :data="entries"><el-table-column prop="kind" label="操作" /><el-table-column prop="available_delta" label="可用变动" /><el-table-column prop="frozen_delta" label="冻结变动" /><el-table-column prop="created_at" label="记录时间" /></el-table></div>
          <div class="panel"><h2>提现记录</h2><el-table :data="withdrawals"><el-table-column prop="amount" label="金额" /><el-table-column label="状态"><template slot-scope="s">{{ label(s.row.state) }}</template></el-table-column><el-table-column prop="reason" label="处理原因" /></el-table></div>
        </section>
        <section v-if="section === 'notifications'" class="panel"><article v-for="item in rows" :key="item.id" class="notification"><div><h2>{{ item.title }} <el-tag v-if="!item.read_at" size="mini">未读</el-tag></h2><p>{{ item.body }}</p></div><el-button :disabled="!!item.read_at" @click="readNotification(item)">标为已读</el-button></article><el-empty v-if="!rows.length" description="暂无通知" /></section>
        <section v-if="section === 'operations'">
          <div v-if="can('operations:read')" class="panel"><h2>运行与待处理事项</h2><div class="summary-grid"><div v-for="(value, key) in backlog" :key="key"><span>{{ backlogNames[key] }}</span><strong>{{ value }}</strong></div></div><el-button @click="downloadSpec">下载接口说明</el-button><el-table :data="jobs"><el-table-column prop="job_name" label="维护任务" /><el-table-column prop="last_result" label="结果" /><el-table-column prop="last_success" label="最近成功" /></el-table></div>
          <div v-if="can('withdrawal:manage')" class="panel"><h2>待审批的模拟提现</h2><el-table :data="managedWithdrawals"><el-table-column prop="id" label="提现单号" min-width="260" /><el-table-column prop="userId" label="用户" /><el-table-column prop="regionCode" label="区域" /><el-table-column prop="amount" label="金额" /><el-table-column label="审批"><template slot-scope="s"><el-button type="text" @click="withdrawalDecision(s.row, 'APPROVE')">模拟结算</el-button><el-button type="text" @click="withdrawalDecision(s.row, 'REJECT')">驳回释放</el-button></template></el-table-column></el-table></div>
          <RewardAdministration v-if="can('reward:manage')" />
        </section>
        <Administration v-if="section === 'identity' && can('identity:user:manage')" :actor="actor" />
        <div v-if="['campaigns','reports','reviews','wallet','notifications'].includes(section)" class="pagination"><el-button :disabled="page === 1" @click="page--; refresh()">上一页</el-button><el-button :disabled="rows.length < 20" @click="page++; refresh()">下一页</el-button></div>
      </main>
      <el-dialog title="证据图片" :visible.sync="pictureVisible" width="70%" @closed="clearPicture"><img :src="picture" alt="线索证据" class="evidence-picture"></el-dialog>
      <el-dialog title="人工审核" :visible.sync="reviewVisible" width="680px"><p>线索 #{{ reviewing.reportId }} · {{ reviewing.stage === 'RECHECK' ? '独立复核' : '初审' }}</p><el-button @click="preview('/review-tasks/' + reviewing.id + '/evidence')">查看证据图片</el-button><p class="muted">模型分数 {{ reviewing.score }}，仅供风险筛查。请根据征集规则与证据独立判断。</p><el-input v-model="decisionReason" type="textarea" :rows="4" maxlength="500" placeholder="请填写具体审核原因" /><span slot="footer"><el-button v-if="reviewing.stage === 'PRIMARY'" @click="decide('REQUEST_RECHECK')">提交独立复核</el-button><el-button type="danger" @click="decide('REJECT')">驳回</el-button><el-button type="primary" @click="decide('APPROVE')">审核通过</el-button></span></el-dialog>
      <el-dialog :title="detailTitle" :visible.sync="detailVisible" width="70%"><pre class="detail">{{ detail }}</pre></el-dialog>
    </template>
  </div>
</template>

<script>
import { api, requestKey, message } from './client'
import Administration from './Administration.vue'
import RewardAdministration from './RewardAdministration.vue'
const names = { DRAFT: '草稿', PUBLISHED: '征集中', CLOSED: '已关闭', PENDING: '等待检测', RUNNING: '检测中', RETRY_WAIT: '等待重试', SUCCEEDED: '检测完成', DEAD: '需人工处理', WAITING_DETECTION: '等待检测', WAITING_REVIEW: '待初审', RISK_REVIEW: '待独立复核', READY: '可领取', CLAIMED: '审核中', MANUAL_REQUIRED: '需人工处理', APPROVED: '审核通过', REJECTED: '已驳回', NONE: '尚未开始', RESERVED: '预算已预留', CREDITED: '已入账', CANCELLED: '已取消', REVERSED: '已冲回', REQUESTED: '待审批', SIMULATED_PAID: '已模拟结算' }
export default {
  components: { Administration, RewardAdministration },
  data() { return { actor: null, login: { username: '', password: '' }, busy: false, error: '', section: 'campaigns', page: 1, rows: [], campaigns: [], campaign: { title: '', regionCode: '', rewardAmount: 3.5, budgetAmount: 1000 }, windowRange: [new Date(), new Date(Date.now() + 7 * 86400000)], report: { campaignId: null, location: '', description: '' }, captureTime: new Date(), file: null, evidenceId: null, submitKey: requestKey(), wallet: {}, entries: [], withdrawals: [], withdrawAmount: 1, withdrawRegion: '', withdrawalKey: requestKey(), reviewStatus: 'READY', claims: {}, reviewing: {}, reviewVisible: false, decisionReason: '', picture: '', pictureVisible: false, detailTitle: '', detail: '', detailVisible: false, backlog: {}, jobs: [], managedWithdrawals: [], financialId: '', descriptions: { campaigns: '按区域征集交通线索，查看规则与奖励。', reports: '提交证据并跟踪检测、审核和奖励进度。', reviews: '领取区域工单，保留每一次处理依据。', wallet: '查看奖励、不可变流水及模拟提现记录。', notifications: '跟踪线索处理和奖励变化。', operations: '处理异常、预算与模拟结算，追踪维护结果。' }, backlogNames: { outboxPending: '待投递消息', outboxDead: '投递失败', detectionDead: '检测异常', manualReviews: '待人工转派', manualCorrections: '待人工追偿', reconciliationDrifts: '对账差异' } } },
  computed: { navigation() { return [{ key: 'campaigns', label: '专项征集', show: true }, { key: 'reports', label: '我的线索', show: this.can('report:read') || this.can('report:review') }, { key: 'reviews', label: '审核工作台', show: this.actor.permissions.some(p => p.startsWith('review:')) }, { key: 'wallet', label: '奖励与提现', show: this.can('wallet:read') }, { key: 'notifications', label: '站内通知', show: this.can('notification:read') }, { key: 'operations', label: '运营管理', show: this.can('operations:read') || this.can('withdrawal:manage') || this.can('reward:manage') }].filter(x => x.show) }, sectionTitle() { return (this.navigation.find(x => x.key === this.section) || {}).label || '工作台' } },
  async created() { this.expiryHandler = () => { this.actor = null; this.claims = {}; this.error = '登录会话已失效，请重新登录' }; window.addEventListener('traffic-session-expired', this.expiryHandler); if (api.hasSession()) await this.perform(async () => { this.actor = await api.get('/auth/me'); this.withdrawRegion = this.actor.regionCodes[0] || ''; await this.load() }) },
  beforeDestroy() { window.removeEventListener('traffic-session-expired', this.expiryHandler); this.clearPicture() },
  methods: {
    can(permission) { return !!this.actor && this.actor.permissions.includes(permission) }, label(value) { return names[value] || value },
    async perform(action) { if (this.busy) return; this.busy = true; this.error = ''; try { await action() } catch (e) { if (e !== 'cancel' && e !== 'close') { this.error = message(e); this.$message.error(this.error) } } finally { this.busy = false } },
    signIn() { this.perform(async () => { this.actor = await api.login(this.login.username, this.login.password); this.login.password = ''; this.withdrawRegion = this.actor.regionCodes[0] || ''; this.campaign.regionCode = this.withdrawRegion; await this.load() }) },
    signOut() { this.perform(async () => { try { await api.logout() } finally { this.actor = null; this.claims = {}; this.clearPicture() } }) },
    changeSection(section) { this.section = section; this.page = 1; this.refresh() }, reload() { this.page = 1; this.refresh() }, refresh() { this.perform(() => this.load()) },
    async load() { const params = { page: this.page, size: 20 }; if (this.section === 'campaigns') this.rows = (await api.get('/campaigns', params)).items;
      if (this.section === 'reports') { this.rows = (await api.get('/reports', params)).items; this.campaigns = (await api.get('/campaigns', { size: 100 })).items.filter(c => c.state === 'PUBLISHED') }
      if (this.section === 'reviews') this.rows = (await api.get('/review-tasks', Object.assign(params, this.reviewStatus ? { status: this.reviewStatus } : {}))).items;
      if (this.section === 'wallet') { this.wallet = await api.get('/wallet'); this.rows = (await api.get('/rewards', params)).items; this.entries = (await api.get('/wallet/entries', params)).items; this.withdrawals = (await api.get('/withdrawals', params)).items }
      if (this.section === 'notifications') this.rows = (await api.get('/notifications', params)).items;
      if (this.section === 'operations') { if (this.can('operations:read')) { const result = await api.get('/operations/summary'); this.jobs = result.jobs; delete result.jobs; this.backlog = result } if (this.can('withdrawal:manage')) this.managedWithdrawals = (await api.get('/management/withdrawals', { state: 'REQUESTED' })).items }
    },
    createCampaign() { this.perform(async () => { if (!this.windowRange || !this.windowRange[0]) throw new Error('请选择征集时间'); await api.post('/campaigns', Object.assign({}, this.campaign, { startsAt: this.windowRange[0].toISOString(), endsAt: this.windowRange[1].toISOString() })); this.campaign.title = ''; await this.load() }) },
    campaignAction(row, action) { this.perform(async () => { await this.$confirm(`确认${action === 'publish' ? '发布' : '关闭'}此征集任务？`, '征集管理'); await api.post(`/campaigns/${row.id}/${action}`, {}); await this.load() }) },
    prepareReport(row) { this.report.campaignId = row.id; this.changeSection('reports') }, selectImage(event) { this.file = event.target.files[0] || null; this.evidenceId = null; this.submitKey = requestKey() },
    submitReport() { this.perform(async () => { if (!this.report.campaignId || !this.file || !this.captureTime) throw new Error('请完整填写线索并选择图片'); if (!this.evidenceId) this.evidenceId = (await api.upload(this.file)).id; await api.post('/reports', Object.assign({}, this.report, { evidenceId: this.evidenceId, captureTime: this.captureTime.toISOString() }), this.submitKey); this.$message.success('线索已提交，请跟踪处理进度'); this.file = null; this.evidenceId = null; this.submitKey = requestKey(); await this.load() }) },
    appeal(row) { this.perform(async () => { const input = await this.$prompt('每条已驳回线索只能申请一次，请填写理由', '申请独立复核', { inputPattern: /\S/, inputErrorMessage: '请填写理由' }); await api.post(`/reports/${row.id}/appeals`, { reason: input.value }); await this.load() }) },
    async preview(url) { try { this.clearPicture(); this.picture = await api.image(url); this.pictureVisible = true } catch (e) { this.error = message(e) } }, clearPicture() { if (this.picture) URL.revokeObjectURL(this.picture); this.picture = '' },
    claim(row) { this.perform(async () => { const claim = await api.post(`/review-tasks/${row.id}/claim`, { expectedVersion: row.version }); this.$set(this.claims, row.id, claim); this.reviewing = Object.assign({}, row, claim); this.decisionReason = ''; this.reviewVisible = true; await this.load() }) }, openReview(row) { this.reviewing = Object.assign({}, row, this.claims[row.id]); this.reviewVisible = true },
    decide(decision) { this.perform(async () => { const claim = this.claims[this.reviewing.id]; if (!claim || !this.decisionReason.trim()) throw new Error('请填写审核原因'); await api.post(`/review-tasks/${claim.id}/decisions`, { version: claim.version, leaseToken: claim.leaseToken, decision, reason: this.decisionReason }); this.$delete(this.claims, claim.id); this.reviewVisible = false; await this.load() }) },
    audit(row) { this.perform(async () => { this.show('工单操作记录', (await api.get(`/review-tasks/${row.id}/audit`)).items) }) },
    reassign(row) { this.perform(async () => { const target = await this.$prompt('填写目标审核员用户编号', '指定转派'); const reason = await this.$prompt('填写转派原因', '指定转派'); await api.post(`/review-tasks/${row.id}/reassign`, { expectedVersion: row.version, targetReviewerId: Number(target.value), reason: reason.value }); await this.load() }) },
    budget(row) { this.perform(async () => { const budget = await api.get(`/campaigns/${row.id}/budget`); const input = await this.$prompt(`总额 ¥${budget.total}，占用 ¥${budget.reserved}，支出 ¥${budget.spent}。填写追加金额，取消则只查看。`, '任务预算'); const reason = await this.$prompt('填写追加原因', '预算追加'); await api.post(`/campaigns/${row.id}/budget-additions`, { amount: Number(input.value), reason: reason.value }, requestKey()); await this.load() }) },
    withdraw() { this.perform(async () => { await api.post('/withdrawals', { amount: this.withdrawAmount, regionCode: this.withdrawRegion }, this.withdrawalKey); this.withdrawalKey = requestKey(); await this.load(); this.$message.success('模拟提现申请已提交') }) },
    withdrawalDecision(row, decision) { this.perform(async () => { const input = await this.$prompt('填写审批依据；系统禁止自审批', '模拟提现审批'); await api.post(`/withdrawals/${row.id}/decisions`, { decision, reason: input.value }); await this.load() }) },
    readNotification(row) { this.perform(async () => { await api.post(`/notifications/${row.id}/read`, {}); await this.load() }) },
    financial(action) { this.perform(async () => { const input = await this.$prompt('请确认关联记录并填写操作原因', action === 'activate' ? '历史意图激活' : '奖励更正'); const result = await api.post(action === 'activate' ? `/approval-intents/${this.financialId}/activate` : `/rewards/${this.financialId}/corrections`, { reason: input.value }); this.show('处理结果', result); await this.load() }) },
    show(title, data) { this.detailTitle = title; this.detail = JSON.stringify(data, null, 2); this.detailVisible = true },
    downloadSpec() { this.perform(async () => { const value = await api.specification(); const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = 'traffic-openapi.json'; a.click(); URL.revokeObjectURL(url) }) }
  }
}
</script>

<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#24334b;font-family:Inter,"Microsoft YaHei",sans-serif}.traffic-app{min-height:100vh}.sidebar{position:fixed;inset:0 auto 0 0;width:224px;padding:34px 18px;background:#15243b;color:#eaf0f8;display:flex;flex-direction:column}.brand{font-weight:700;font-size:22px;margin:0 12px 38px}.brand span{display:block;font-size:11px;font-weight:400;letter-spacing:3px;color:#90a5c1;margin-top:12px}.sidebar>button{padding:14px 18px;margin:3px 0;border:0;background:transparent;color:#b7c5d9;text-align:left;border-radius:7px;font-size:15px;cursor:pointer}.sidebar>button.active{background:#294564;color:#fff}.sidebar-bottom{margin-top:auto;padding:18px 12px;font-size:14px}.sidebar-bottom span{display:block;margin-top:8px;color:#90a5c1;font-size:12px}.workspace{margin-left:224px;max-width:1560px;padding:36px 44px 60px}.eyebrow{font-size:11px;letter-spacing:2px;color:#6380a0}h1{font-size:29px;margin:12px 0;font-weight:650}h2{font-size:17px;margin:0 0 22px}.muted{color:#7b899b;line-height:1.8}.small{font-size:12px;margin-left:10px}.toolbar{display:flex;align-items:center;gap:16px;margin:25px 0 18px}.panel{background:white;border:1px solid #e5eaf0;border-radius:10px;padding:26px;margin-bottom:22px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 28px}.el-select,.el-date-editor.el-input{max-width:100%}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.stats .panel strong{display:block;font-size:30px;margin-top:16px;color:#24476a}.stats .panel span{color:#7b899b}.stats .stat-label{font-size:22px!important}.summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-bottom:28px}.summary-grid strong{display:block;font-size:26px;margin-top:10px}.summary-grid span{font-size:13px;color:#7b899b}.notification{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eef1f5;padding:20px 0}.notification h2{margin:0}.notification p{font-size:14px;color:#63758c}.notice{margin:18px 0}.evidence-picture{display:block;max-width:100%;max-height:70vh;margin:auto}.detail{white-space:pre-wrap;word-break:break-word;font-size:13px;max-height:60vh;overflow:auto}.pagination{display:flex;justify-content:flex-end;gap:12px}.login-card{max-width:450px;margin:12vh auto;padding:42px;background:white;border:1px solid #e4eaf1;border-radius:14px;box-shadow:0 12px 50px #122a4b0a}.login-card .el-button{width:100%}.login-card .small{margin:24px 0 0}.error{color:#b33b39;font-size:13px}.el-input-number+.el-select{margin:0 14px}.el-table .el-button+.el-button{margin-left:12px}@media(max-width:850px){.sidebar{position:relative;width:auto;padding:20px;display:block}.brand{margin:0 0 15px}.brand span,.sidebar-bottom{display:none}.sidebar>button{display:inline-block;font-size:13px;padding:10px}.workspace{margin:0;padding:24px 18px}.form-grid{grid-template-columns:1fr}.stats{gap:10px}.stats .panel{padding:15px}.stats .panel strong{font-size:22px}.summary-grid{grid-template-columns:repeat(2,1fr)}}
</style>
<style>
.sidebar-bottom .el-button>span{display:inline;margin:0;color:inherit}
@media(max-width:850px){.sidebar .sidebar-bottom{display:block;padding:10px 14px;margin-top:8px}.sidebar .sidebar-bottom>span{display:none}.sidebar .sidebar-bottom .el-button{margin-left:18px}.workspace .el-form--inline .el-form-item{display:block;max-width:100%}.workspace .el-form--inline .el-form-item__content{display:block;width:100%}.workspace .el-date-editor--datetimerange{width:100%}}
</style>
